1	import Foundation
2	
3	/// A clip as the tutorials' clip filter sees it (spec §11 TU-2 (3)): the five
4	/// keys a `needs`, a `selection` wait or a `$pick` may name, answered for one
5	/// clip of one snapshot.
6	///
7	/// `tools/proof/tutorial_probe.swift` answers these per clip of the bundled
8	/// practice project, so `tutorial_check.py` can hold every tutorial's `needs`
9	/// to it (TU-7); TU2's runner calls `matches(_:)` for its waits and picks.
10	struct TutorialClipFacts: Equatable {
11	    /// The filter's keys, in TU-2 (3)'s order; `dictionary` answers exactly these.
12	    static let keys = ["has_sound", "has_pixels", "kind", "follows_clip", "has_transition"]
13	    /// `kind`'s values: every `ClipSource` case name.
14	    static let kinds = ["media", "still", "image", "text", "shape", "graphic", "nest", "adjustment"]
15	
16	    /// The clip has an `audio` group.
17	    let hasSound: Bool
18	    /// The clip has a `video` group and is not an adjustment clip (which grades
19	    /// what is behind it and draws nothing of its own).
20	    let hasPixels: Bool
21	    /// The `ClipSource` case name (`ClipSource.kindName`).
22	    let kind: String
23	    /// The previous clip on its track (by start, then id) exists and this clip
24	    /// starts at or before that clip's end.
25	    let followsClip: Bool
26	    /// The clip's `transition_in` is not null.
27	    let hasTransition: Bool
28	
29	    init(clip: ClipSnapshot, in snapshot: ProjectSnapshot) {
30	        hasSound = clip.audio != nil
31	        if case .adjustment = clip.source {
32	            hasPixels = false
33	        } else {
34	            hasPixels = clip.video != nil
35	        }
36	        kind = clip.source.kindName
37	        let earlier = snapshot.clips.filter {
38	            $0.track == clip.track && $0.id != clip.id
39	                && ($0.start < clip.start || ($0.start == clip.start && $0.id < clip.id))
40	        }
41	        let previous = earlier.max { lhs, rhs in
42	            lhs.start != rhs.start ? lhs.start < rhs.start : lhs.id < rhs.id
43	        }
44	        if let previous {
45	            followsClip = clip.start <= previous.start + previous.duration
46	        } else {
47	            followsClip = false
48	        }
49	        hasTransition = clip.transitionIn != nil
50	    }
51	
52	    /// The five keys and their values, as the filter spells them.
53	    var dictionary: [String: Any] {
54	        [
55	            "has_sound": hasSound,
56	            "has_pixels": hasPixels,
57	            "kind": kind,
58	            "follows_clip": followsClip,
59	            "has_transition": hasTransition,
60	        ]
61	    }
62	
63	    /// Whether every key `filter` names holds here (`{}` matches any clip). A
64	    /// key outside `keys`, or a value of the wrong type, matches nothing.
65	    func matches(_ filter: [String: Any]) -> Bool {
66	        let mine = dictionary
67	        for (key, wanted) in filter {
68	            guard let have = mine[key] else { return false }
69	            if let have = have as? String {
70	                guard let wanted = wanted as? String, wanted == have else { return false }
71	            } else if let have = have as? Bool {
72	                guard let wanted = wanted as? Bool, wanted == have else { return false }
73	            } else {
74	                return false
75	            }
76	        }
77	        return true
78	    }
79	}
