import AppKit

/// Help ▸ Tutorials (spec §11 TU-6, TU-7): today one item, Open Practice
/// Project, which opens the bundled practice project as an untitled copy
/// (`PracticeProject.open()`); `new_project {practice: true}` is its MCP
/// mirror.
///
/// A nil-target selector on the delegate, like `showGraphicsReference`, so it
/// resolves with no document open; `AppDelegate.validateMenuItem` enables it
/// while the bundle holds the practice project. No key equivalent: every bare
/// letter belongs to the editor's own `keyDown` (spec §9).
extension AppDelegate {

    /// "Tutorials". TU3 inserts one submenu per guide page and a separator at
    /// the top, filled from `Tutorials.json`; Open Practice Project stays last.
    func tutorialsMenu() -> NSMenu {
        let menu = NSMenu(title: "Tutorials")
        menu.addItem(
            item("Open Practice Project", #selector(AppDelegate.openPracticeProject(_:))))
        return menu
    }

    /// Help ▸ Tutorials ▸ Open Practice Project. The error alert is posted a
    /// turn later, so the action returns once its window is up.
    @objc func openPracticeProject(_ sender: Any?) {
        do {
            try PracticeProject.open()
        } catch {
            DispatchQueue.main.async { NSApp.presentError(error) }
        }
    }
}

